/*
 * Draws the seven placeholder avatars used by PersonService.
 *
 * They are deliberately abstract. The 2019 app hotlinked six stock photographs
 * of real people from six different websites; those are gone (see docs/ASSETS.md),
 * and a portfolio repo has no licence to redistribute photographs of strangers.
 * These are geometric badges generated by this script, so every byte in
 * src/assets/avatars/ traces to a file in the repository.
 *
 *   node tools/build-avatars.js
 */
'use strict';

const fs = require('fs');
const path = require('path');

// Hue carries the gender group, lightness carries the age band. Nothing about a
// person is depicted beyond which of the service's buckets they landed in.
const GROUPS = {
  male: { ring: ['#7fb2d9', '#3d84b8', '#1f4e6d'], label: 'male' },
  female: { ring: ['#d99fc0', '#b8558c', '#6d2a52'], label: 'female' },
  unspecified: { ring: ['#8f9aa5'], label: 'unspecified' },
};

const BANDS = [
  { name: 'child', head: 30, shoulder: 52, cy: 82 },
  { name: 'adult', head: 26, shoulder: 62, cy: 78 },
  { name: 'senior', head: 25, shoulder: 58, cy: 78 },
];

function svg(fill, band, label) {
  const { head, shoulder, cy } = band;
  const top = cy + head + 6;
  return [
    '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200" width="200" height="200"',
    ` role="img" aria-label="${label} placeholder avatar">`,
    `<circle cx="100" cy="100" r="100" fill="${fill}"/>`,
    `<circle cx="100" cy="${cy}" r="${head}" fill="#ffffff" opacity="0.92"/>`,
    `<path d="M100 ${top}`,
    ` c-${shoulder} 0 -${shoulder + 8} ${Math.round(shoulder * 0.72)} -${shoulder + 8} ${Math.round(shoulder * 1.02)}`,
    ` h${(shoulder + 8) * 2}`,
    ` c0 -${Math.round(shoulder * 0.3)} -${8} -${Math.round(shoulder * 1.02)} -${shoulder} -${Math.round(shoulder * 1.02)}`,
    ' z" fill="#ffffff" opacity="0.92"/>',
    '</svg>',
    '',
  ].join('');
}

const out = path.join(__dirname, '..', 'src', 'assets', 'avatars');
const written = [];

for (const [group, spec] of Object.entries(GROUPS)) {
  if (group === 'unspecified') {
    const file = 'unspecified.svg';
    fs.writeFileSync(path.join(out, file), svg(spec.ring[0], BANDS[1], spec.label));
    written.push(file);
    continue;
  }
  BANDS.forEach((band, i) => {
    const file = `${group}-${band.name}.svg`;
    fs.writeFileSync(path.join(out, file), svg(spec.ring[i], band, `${spec.label} ${band.name}`));
    written.push(file);
  });
}

console.log(`wrote ${written.length} avatars:\n  ${written.join('\n  ')}`);
